(()=>{
'use strict';
const C=BurrinhoCore,ids=['mario','princess-peach','rosalina','luigi','donkey-kong','bowser','daisy'];
const characters=ids.map(id=>MEMORY_IMAGES.find(im=>im.id==='nintendo-'+id));
let game=null,selected=null,timer=0,message='';
const app=()=>document.getElementById('app');
function stop(){clearTimeout(timer);game=null;selected=null;}
function portrait(n){const c=characters[n];return '<img src="'+c.asset+'" alt="'+c.name+'" draggable="false">';}
function tile(t){return '<span class="bu-tile">'+portrait(t.a)+portrait(t.b)+'</span>';}
function header(){return '<div class="bu-header"><button id="bu-back">← '+(game?'Temas':'Jogos')+'</button><h1>Burrinho</h1><span>Nintendo</span></div>';}
function bindBack(){document.getElementById('bu-back').onclick=()=>game?setup():home();}
function setup(){stop();document.body.dataset.section='burrinho';app().innerHTML='<section class="bu-page">'+header()+'<div class="bu-welcome"><span class="bu-eyebrow">COMBINE OS PERSONAGENS</span><h2>Uma pescaria de amigos!</h2><p>Escolha um tema para começar.</p><button class="bu-theme" id="bu-nintendo"><span class="bu-theme-faces">'+[0,1,3].map(portrait).join('')+'</span><strong>Nintendo <span>↗</span></strong><small>Mario e sua turma · jogar contra o computador</small></button><p class="bu-rules">Cada jogador começa com 3 pedras. Encaixe personagens iguais nas pontas. Não tem uma pedra que sirva? Pesque até encontrar! Vence quem ficar sem pedras primeiro.</p><details><summary>Como jogar</summary><p>Toque numa pedra iluminada e escolha a ponta onde quer encaixar. O primeiro jogador é sorteado e pode abrir com qualquer pedra. Com o monte vazio, passe a vez quando não tiver jogada. Se ambos ficarem sem jogada, a partida termina empatada.</p></details></div></section>';bindBack();document.getElementById('bu-nintendo').onclick=start;}
function start(){stop();game=C.create();message=game.turn?'O computador começa desta vez.':'Você começa! Escolha uma pedra.';render();cpu();}
function render(){
 const s=game;if(!s)return;const ownTurn=!s.over&&s.turn===0,available=C.moves(s,0),t=s.hands[0].find(t=>t.id===selected),valid=t?C.sides(s,t):[],ends=C.ends(s);
 app().innerHTML='<section class="bu-page bu-play">'+header()+'<div class="bu-opponent"><span>Computador</span><span class="bu-backs" aria-label="'+s.hands[1].length+' pedras">'+Array.from({length:Math.min(s.hands[1].length,10)},()=>'<i>✦</i>').join('')+'</span><b>'+s.hands[1].length+'</b></div><p class="bu-status" role="status" aria-live="polite">'+(s.over?(s.winner===0?'Você venceu! 🎉':s.winner===1?'O computador venceu. Vamos tentar de novo?':'Empate! Ninguém consegue encaixar.'):(ownTurn?'Sua vez · ':'Vez do computador · ')+message)+'</p><div class="bu-table"><div class="bu-chain" tabindex="0" aria-label="Pedras na mesa; role para ver todas">'+(s.board.length?s.board.map(tile).join(''):'<p>Jogue a primeira pedra aqui ✨</p>')+'</div></div><div class="bu-actions">'+(s.board.length?['left','right'].map((side,i)=>'<button data-side="'+side+'" '+(!ownTurn||!valid.includes(side)?'disabled':'')+'>'+portrait(ends[i])+'<span>Encaixar à '+(i?'direita':'esquerda')+'</span></button>').join(''):'<button data-side="right" '+(!ownTurn||!t?'disabled':'')+'>Colocar na mesa</button>')+'<button id="bu-draw" '+(!ownTurn||available.length||!s.stock.length?'disabled':'')+'>🎣 Pescar <small>'+s.stock.length+' no monte</small></button>'+(!s.stock.length&&!available.length&&ownTurn?'<button id="bu-pass">Passar a vez</button>':'')+'</div><div class="bu-hand-label">Suas pedras <span>'+s.hands[0].length+'</span></div><div class="bu-hand">'+s.hands[0].map(t=>{const ok=ownTurn&&C.sides(s,t).length;return '<button class="'+(selected===t.id?'bu-selected':'')+'" data-tile="'+t.id+'" '+(!ok?'disabled':'')+' aria-pressed="'+(selected===t.id)+'" aria-label="'+characters[t.a].name+' e '+characters[t.b].name+'">'+tile(t)+'</button>';}).join('')+'</div>'+(s.over?'<div class="bu-finish"><button id="bu-again">Jogar de novo ↻</button><button id="bu-themes">Escolher tema</button></div>':'')+'</section>';
 bindBack();app().querySelectorAll('[data-tile]').forEach(b=>b.onclick=()=>{selected=b.dataset.tile;message='Escolha uma das pontas para encaixar.';render();});
 app().querySelectorAll('[data-side]').forEach(b=>b.onclick=()=>{if(C.play(game,0,selected,b.dataset.side)){selected=null;message='Escolhendo uma pedra…';render();cpu();}});
 document.getElementById('bu-draw').onclick=()=>{if(C.draw(game,0)){const t=game.hands[0].at(-1);selected=C.sides(game,t).length?t.id:null;message=selected?'Você pescou uma pedra que serve! Escolha a ponta.':'Essa não serve. Pesque mais uma.';render();}};
 const pass=document.getElementById('bu-pass');if(pass)pass.onclick=()=>{C.pass(game,0);message='Você passou a vez.';render();cpu();};
 const again=document.getElementById('bu-again');if(again){again.onclick=start;document.getElementById('bu-themes').onclick=setup;}
}
function cpu(){clearTimeout(timer);if(!game||game.over||game.turn!==1)return;timer=setTimeout(()=>{if(!game||game.over||game.turn!==1)return;const options=C.moves(game);if(options.length){const doubles=options.filter(m=>{const t=game.hands[1].find(t=>t.id===m.id);return t.a===t.b;}),pool=doubles.length?doubles:options,m=pool[Math.floor(Math.random()*pool.length)];C.play(game,1,m.id,m.side);message=C.moves(game,0).length?'Escolha uma pedra iluminada.':'Pesque uma pedra no monte.';}else if(game.stock.length){C.draw(game,1);message='O computador pescou uma pedra.';}else{C.pass(game,1);message='O computador passou a vez.';}render();cpu();},850);}
const oldHome=home;home=function(){stop();oldHome();const cards=app().querySelector('.game-cards');if(!cards)return;cards.insertAdjacentHTML('beforeend','<button class="game-card" id="bu-open"><div class="game-cover bu-cover">'+tile({a:0,b:1})+tile({a:3,b:4})+'<span class="cover-badge">🎣 COMBINE E PESQUE</span></div><div class="game-card-copy"><small>DOMINÓ DE PERSONAGENS</small><h2>Burrinho <span>↗</span></h2><p>Encaixe os amigos e seja o primeiro a ficar sem pedras.</p></div></button>');document.getElementById('bu-open').onclick=setup;};
const oldCatalog=showCatalog;showCatalog=function(){stop();oldCatalog();};window.addEventListener('pagehide',stop);home();
})();
